&lt;h2&gt;&lt;strong&gt;Das bewegst du:&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW179605223 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW179605223 BCX8&quot;&gt;Als &lt;strong&gt;Associate &lt;/strong&gt;&lt;/span&gt;&lt;strong&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW179605223 BCX8&quot;&gt;Director&lt;/span&gt;&lt;/strong&gt;&lt;span class=&quot;NormalTextRun SCXW179605223 BCX8&quot;&gt;&lt;strong&gt; Digital Media (Mensch)&lt;/strong&gt; im Bereich Digital führst du ein Team von Digital Media Plan&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW179605223 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW179605223 BCX8&quot;&gt;ern und Digital&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW179605223 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW179605223 BCX8&quot;&gt;Campaign&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW179605223 BCX8&quot;&gt;Managern&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW179605223 BCX8&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW179605223 BCX8&quot; lang=&quot;DE-DE&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW179605223 BCX8&quot;&gt;und entwickelst gemeinsam mit ihnen innovative Kampagnen für renommierte Kunden. Du übernimmst dabei sowohl strategische Verantwortung als auch die fachliche und organisatorische Führung deines Teams.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;strong&gt;Strategie:&lt;/strong&gt; Du bist für die strategische Entwicklung und Qualitätssicherung von Media-Strategien und -Plänen für digitale Medien (u.a. Display, Video, Mobile, Social, Search) verantwortlich.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;Kampagnen: &lt;/strong&gt;Die Steuerung und Optimierung&amp;nbsp;&lt;span data-contrast=&quot;none&quot;&gt;des Campaign Managements&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;unter Berücksichtigung effizienter Prozesse und hoher Qualitätsstandards liegen bei dir.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;Teamführung:&lt;/strong&gt; Du führst fachlich und organisatorisch und kümmerst dich um die Weiterentwicklung deines Teams.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;Projekte:&lt;/strong&gt; Du trägst die Verantwortung für die Koordination komplexer, digitaler Projekte in enger Zusammenarbeit mit Kundenteams, Kreativagenturen, Vermarktern und internen Spezialabteilungen.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;Marktscreening:&amp;nbsp;&lt;/strong&gt;Du nimmst eine kontinuierliche&lt;strong&gt; &lt;/strong&gt;Marktbeobachtung vor und leitest neue Potenziale für Wachstum und Innovation ab.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;Stakeholder:&lt;/strong&gt; Du übernimmst Ergebnisverantwortung für Reportings, Analysen und Präsentationen für internen Stakeholder.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Das zeichnet dich aus:&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;strong&gt;Berufserfahrung:&amp;nbsp;&lt;/strong&gt;Du bringst mehrjährige Berufserfahrung in der digitalen Mediaplanung, -beratung oder im Kampagnen-Management mit, idealerweise mit erster Führungserfahrung.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;Qualifikation: &lt;/strong&gt;Du hast ein abgeschlossenes Studium im Bereich Wirtschafts-, Kommunikations- oder Medienwissenschaften oder vergleichbare Ausbildung in der Medien- oder Werbebranche.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;Tools:&lt;/strong&gt; Du verfügst über fundierte Kenntnisse der gängigen Planungstools und digitalen Kanäle.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;Analysefähigkeit:&lt;/strong&gt; Du hast ausgeprägte analytische Fähigkeiten sowie eine strukturierte, lösungsorientierte Arbeitsweise.&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;Überzeugungskraft: &lt;/strong&gt;Du überzeugst mit starker Kundenorientierung, Durchsetzungsvermögen und souveränem Auftreten.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Sprachkenntnisse: &lt;/strong&gt;Deine Deutsch- und Englischkenntnisse sind verhandlungssicher.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Darüber hinaus bist du:&lt;strong&gt;&amp;nbsp;#motivierend #lösungsorientiert #kommunikativ&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Wenn du diesen Job spannend findest, dann ermutigen wir dich ausdrücklich zur Bewerbung, auch wenn du nicht jede oben gelistete Qualifikation aufweisen kannst.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Arbeiten bei WPP Media:&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;Als WPP Media gestalten wir die Zukunft der Medien und investieren dabei konsequent in unsere Mitarbeiter:innen. Jede:r Kolleg:in genießt die Vorteile des globalen Netzwerks von WPP Media und WPP, um sich weiterzuentwickeln&amp;nbsp;und an der Spitze von Marketing und Werbung zu lernen. Vielfalt und Zusammenhalt leben wir durch zahlreiche Employee Resource Groups und regelmäßige interne Events - zum Austausch, zur Inspiration und zum gemeinsamen Feiern unserer Erfolge.&lt;br&gt;&amp;nbsp;&lt;br&gt;WPP Media ist ein Arbeitgeber, der Chancengleichheit fördert. Wir berücksichtigen alle Bewerber:innen für alle Positionen ohne Diskriminierung. Unser Ziel ist eine Kultur des Respekts und der Zugehörigkeit, in der jede:r die gleichen Möglichkeiten hat, sich einzubringen und beruflich zu wachsen.&lt;/p&gt;
&lt;p&gt;Bitte lies unsere &lt;a href=&quot;https://www.wppmedia.com/pages/privacy-policy&quot;&gt;Datenschutzerklärung&lt;/a&gt; für Deutschland, Österreich und die Schweiz, um weitere Informationen darüber zu erhalten, wie wir die von dir bereitgestellten Daten verarbeiten. #LIpromoted&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW227196529 BCX8&quot; lang=&quot;EN-CA&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW227196529 BCX8&quot;&gt;Please read our &lt;a href=&quot;https://www.wppmedia.com/pages/privacy-policy#:~:text=WPP%20Media%20Privacy%20Notice%20for%20Recruitment&quot;&gt;Privacy Notice&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW227196529 BCX8&quot; lang=&quot;EN-CA&quot; data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;span class=&quot;NormalTextRun SCXW227196529 BCX8&quot;&gt;for more information on how we process the information you provide.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW227196529 BCX8&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.com">Jobs in Germany</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p class=&quot;sc-gEkIjz cjtSrT MuiTypography-root MuiTypography-body1 sc-hoLEA&quot;&gt;Raisin is the world’s leading platform for savings and investment products. Founded in 2012, the&amp;nbsp;&lt;strong&gt;FinTech&lt;/strong&gt; connects consumers with banks in the EU, the UK and the US. This gives consumers &lt;strong&gt;better interest rates&lt;/strong&gt; and banks a &lt;strong&gt;diversified form of refinancing&lt;/strong&gt;. Our vision is to offer savings and investments without barriers and thus open up the global 160 trillion euro market.&lt;/p&gt;
&lt;p class=&quot;sc-gEkIjz cjtSrT MuiTypography-root MuiTypography-body1 sc-hoLEA&quot;&gt;Raisin currently employs more than 800 people from over 75 countries worldwide. Today, the platform holds over 80 billion euros in assets from&amp;nbsp;&lt;strong&gt;more than one million investors&lt;/strong&gt; which have accrued over 5 billion euros in returns.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;Team:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The Customer Engagement Team at Raisin is a dynamic cross-functional unit shaping the design and experience of our core customer touchpoints across markets. As a key contributor in this team, you&#39;ll take ownership of foundational domains such as our Customer Portal Dashboard on both web and mobile, ensuring consistent, engaging, and scalable user experiences. You&#39;ll also help drive the evolution of our Email Service and champion the delivery of high-impact Transactional Emails that keep our users informed and engaged throughout their journey.&lt;/p&gt;
&lt;p&gt;Beyond technical excellence, you&#39;ll play a central role in people development — mentoring peers, fostering a collaborative engineering culture, and supporting individual growth. We value team health as much as platform quality, and your leadership will be instrumental in both. If you&#39;re passionate about building seamless cross-platform experiences and empowering those around you, the Customer Engagement Team at Raisin offers the ideal space for impactful leadership.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Your Responsibilities&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;You are responsible for the full E2E delivery cycle: from requirements analysis, effort estimation, through design, implementation, QA, and delivery.&lt;/li&gt;
&lt;li&gt;You nurture an inspiring environment with open communication and a culture of trust.&lt;/li&gt;
&lt;li&gt;You proactively resolve impediments and mitigate risks for your team.&lt;/li&gt;
&lt;li&gt;In case you need to escalate delivery and team risks, you do this in a timely fashion, with a well-articulated solution/mitigation plan.&lt;/li&gt;
&lt;li&gt;You collaborate closely with your team’s Product Manager and Tech Lead.&lt;/li&gt;
&lt;li&gt;You facilitate the team’s work on strategy and planning for the delivery.&lt;/li&gt;
&lt;li&gt;Together with the Product Manager, you drive the OKR process for your team: communication of objectives, KR definition, team commitment, and pairing OKRs with individual target agreements for your engineers.&lt;/li&gt;
&lt;li&gt;You recruit, hire, and onboard engineers into the team.&lt;/li&gt;
&lt;li&gt;You develop both your engineers’ soft- and technical skill-sets according to the company’s goals and needs.&lt;/li&gt;
&lt;li&gt;You craft agreements and individual development plans with every team member, aligned to the team&#39;s goals.&lt;/li&gt;
&lt;li&gt;You uncover training opportunities as well as provide coaching for your team.&lt;/li&gt;
&lt;li&gt;You recognize high performance and reward accomplishments.&lt;/li&gt;
&lt;li&gt;You establish and keep strong performance standards for your direct reports&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Your Profile&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;You have a university degree in Computer Science, Engineering, Information Systems or related fields or equivalent practical experience.&lt;/li&gt;
&lt;li&gt;You bring at least 1 year of leadership/people management experience.&lt;/li&gt;
&lt;li&gt;You have strong hands-on experience (min. 5 years) as Frontend Engineer. Familiarity with Python, React Native, or PHP is considered a strong plus.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;You have a proven track record of using AI tools to increase productivity, with hands-on proficiency in AI coding agents like Cursor to streamline development and code generation.&lt;/li&gt;
&lt;li&gt;You have proven experience working with UX/UI principles, collaborating closely with designers, and translating user-centered designs into high-quality web/mobile implementations.&lt;/li&gt;
&lt;li&gt;You know how to manage software projects to a successful delivery in collaborative fashion.&lt;/li&gt;
&lt;li&gt;You have up-to-date, in-depth knowledge of the software development lifecycle in a frontend-technology landscape.&lt;/li&gt;
&lt;li&gt;You are comfortable with open code and architecture discussions.&lt;/li&gt;
&lt;li&gt;Fluency in English; German-language skills are a plus but not mandatory.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Join our mission, join our team – and grow with us!&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Raisin, we care about each other and it is one of our top priorities to foster an open and caring environment in which everyone feels welcome and comfortable. Our culture is strongly driven by our ambitious team, which connects more than 75 different nationalities.&lt;/p&gt;
&lt;p&gt;As part of our team, you will benefit from:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Employee Development Budget of €2,000 and four full training days per year.&lt;/li&gt;
&lt;li&gt;Flexible working hours, home office and 30 vacation days.&lt;/li&gt;
&lt;li&gt;A company pension scheme (Betriebliche Altersvorsorge), which we support with 20%.&lt;/li&gt;
&lt;li&gt;Enjoy more than 50+ different sports with Urban Sports Club: We subsidize your membership with more than €20 per month.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Do you miss being in the office? The Deutschland Ticket gets you there, which we subsidize with €25 per month.&lt;/li&gt;
&lt;li&gt;Love cycling? With JobRad, lease the bike of your choice and enjoy tax savings, plus Raisin covers your monthly insurance costs.&lt;/li&gt;
&lt;li&gt;Hungry all the time? Snacks, daily fresh fruit as well as drinks provided at the office.&lt;/li&gt;
&lt;li&gt;You are moving from another country or city to join us? We may support your relocation.&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;a href=&quot;https://www.raisin.com/corporate/raisin-applicant-privacy-policy/&quot;&gt;&lt;em&gt;Raisin Applicant Privacy Policy&lt;/em&gt;&lt;/a&gt;&lt;/p&gt;
&lt;p data-start=&quot;728&quot; data-end=&quot;900&quot;&gt;We value diversity and the unique experiences each individual brings. If you’re excited about this role but don’t meet every requirement, we still encourage you to apply.&lt;/p&gt;
&lt;p data-start=&quot;907&quot; data-end=&quot;1013&quot;&gt;We are an equal opportunity employer and are committed to creating an inclusive environment for everyone, regardless of race, colour, ancestry, religion, sex, national origin, sexual orientation, age, citizenship, marital status, disability, or gender identity.&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.com">Jobs in Germany</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p class=&quot;sc-gEkIjz cjtSrT MuiTypography-root MuiTypography-body1 sc-hoLEA&quot;&gt;Raisin is the world’s leading platform for savings and investment products. Founded in 2012, the&amp;nbsp;&lt;strong&gt;FinTech&lt;/strong&gt; connects consumers with banks in the EU, the UK and the US. This gives consumers &lt;strong&gt;better interest rates&lt;/strong&gt; and banks a &lt;strong&gt;diversified form of refinancing&lt;/strong&gt;. Our vision is to offer savings and investments without barriers and thus open up the global 160 trillion euro market.&lt;/p&gt;
&lt;p class=&quot;sc-gEkIjz cjtSrT MuiTypography-root MuiTypography-body1 sc-hoLEA&quot;&gt;Raisin currently employs more than 800 people from over 75 countries worldwide. Today, the platform holds over 80 billion euros in assets from&amp;nbsp;&lt;strong&gt;more than one million investors&lt;/strong&gt; which have accrued over 5 billion euros in returns.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;strong&gt;Team&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;The Customer Accounting team is responsible for the integration with our Servicing Bank with a focus on accounts and transactions to provide those to the customer and to other services on the Raisin platform. Most importantly, account life cycle, reconciliations and transaction compliance are in the domain of this team.&lt;/p&gt;
&lt;p&gt;The team is part of the “Customer Tribe”, which consists of 5 teams that collaborate closely on the mission to build and run state of the art Customer and Transaction Account experiences to grow Raisin at scale.&lt;/p&gt;
&lt;p&gt;The Customer Accounting team provides:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;the full lifecycle of the transaction accounts&lt;/li&gt;
&lt;li&gt;overview of the account balance and transaction history&lt;/li&gt;
&lt;li&gt;compliance monitoring on transactions&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Tech Stack:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Backend: Java, Spring Boot, MySQL, Kafka, AWS&lt;/li&gt;
&lt;li&gt;Web: TypeScript, ReactJS&lt;/li&gt;
&lt;li&gt;Mobile: TypeScript, React Native&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;br&gt;&lt;strong&gt;Your Responsibilities&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Manage the full E2E delivery cycle: requirements analysis, estimation, design, implementation, QA, and delivery.&lt;/li&gt;
&lt;li&gt;Nurture an inspiring environment with open communication and a culture of trust.&lt;/li&gt;
&lt;li&gt;Proactively resolve impediments and mitigate risks.&lt;/li&gt;
&lt;li&gt;You collaborate closely with your team’s Product Manager.&lt;/li&gt;
&lt;li&gt;Collaborate with other Product Managers and Tech Leads on strategy and planning.&lt;/li&gt;
&lt;li&gt;Drive the OKR process: objectives, definition, and individual target agreements.&lt;/li&gt;
&lt;li&gt;Recruit, hire, and onboard engineers while developing their soft and technical skill-sets.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Your Profile&lt;/strong&gt;&lt;/p&gt;
&lt;h3&gt;&lt;em&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;Leadership &amp;amp; Experience&lt;/strong&gt;&lt;/span&gt;&lt;/em&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;You bring at least 1 year of leadership or people management experience.&lt;/li&gt;
&lt;li&gt;You successfully managed software projects, build sustainable software and delivered in collaborative fashion.&lt;/li&gt;
&lt;li&gt;You feel comfortable and confident driving technical and architectural discussions.&lt;/li&gt;
&lt;li&gt;You are a decisive leader who stands your ground on architectural integrity while remaining a pragmatic and collaborative problem-solver.&lt;/li&gt;
&lt;li&gt;You foster a culture of ownership, accountability, and technical excellence.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;em&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;Expertise&lt;/strong&gt;&lt;/span&gt;&lt;/em&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;You demonstrated critical thinking and problem-solving capabilities&lt;/li&gt;
&lt;li&gt;You possess a strong analytical mind, capable of mapping out intricate transaction flows and identifying edge cases before they hit production.&lt;/li&gt;
&lt;li&gt;You have strong hands-on experience (typically 8+ years) in backend engineering, with solid Java (Spring Boot) expertise.&lt;/li&gt;
&lt;li&gt;You have practical experience with event-driven architectures (e.g., Kafka or comparable technologies).&lt;/li&gt;
&lt;li&gt;You understand distributed systems challenges such as idempotency, consistency and failure handling.&lt;/li&gt;
&lt;li&gt;You are comfortable participating in code reviews and architectural decisions across backend and fullstack systems.&lt;/li&gt;
&lt;li&gt;University degree in Computer Science, Mathematics, or Engineering.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;em&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;Regulated / Fintech Experience (is a plus)&lt;/strong&gt;&lt;/span&gt;&lt;/em&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;You bring professional experience in fintech, banking, investment platforms, insurance, or other highly regulated industries.&lt;/li&gt;
&lt;li&gt;You have worked on systems where data integrity, auditability, compliance, and transactional correctness significantly influenced architectural decisions.&lt;/li&gt;
&lt;li&gt;You have an intrinsic &#39;Safety-First&#39; mindset: For you, auditability and data integrity are not checkboxes, but core features of a professional system.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;em&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;Communication &amp;amp; Collaboration&lt;/strong&gt;&lt;/span&gt;&lt;/em&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;You communicate clearly and confidently with both technical and non-technical stakeholders.&lt;/li&gt;
&lt;li&gt;You are fluent in English; German is a plus but not required.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Join our mission, join our team – and grow with us!&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Raisin, we care about each other and it is one of our top priorities to foster an open and caring environment in which everyone feels welcome and comfortable. Our culture is strongly driven by our ambitious team, which connects more than 75 different nationalities.&lt;/p&gt;
&lt;p&gt;As part of our team, you will benefit from:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Employee Development Budget of €2,000 and four full training days per year.&lt;/li&gt;
&lt;li&gt;Flexible working hours, home office and 30 vacation days.&lt;/li&gt;
&lt;li&gt;A company pension scheme (Betriebliche Altersvorsorge), which we support with 20%.&lt;/li&gt;
&lt;li&gt;Enjoy more than 50+ different sports with Urban Sports Club: We subsidize your membership with more than €20 per month.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Do you miss being in the office? The Deutschland Ticket gets you there, which we subsidize with €25 per month.&lt;/li&gt;
&lt;li&gt;Love cycling? With JobRad, lease the bike of your choice and enjoy tax savings, plus Raisin covers your monthly insurance costs.&lt;/li&gt;
&lt;li&gt;Hungry all the time? Snacks, daily fresh fruit as well as drinks provided at the office.&lt;/li&gt;
&lt;li&gt;You are moving from another country or city to join us? We may support your relocation.&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;a href=&quot;https://www.raisin.com/corporate/raisin-applicant-privacy-policy/&quot;&gt;&lt;em&gt;Raisin Applicant Privacy Policy&lt;/em&gt;&lt;/a&gt;&lt;/p&gt;
&lt;p data-start=&quot;728&quot; data-end=&quot;900&quot;&gt;We value diversity and the unique experiences each individual brings. If you’re excited about this role but don’t meet every requirement, we still encourage you to apply.&lt;/p&gt;
&lt;p data-start=&quot;907&quot; data-end=&quot;1013&quot;&gt;We are an equal opportunity employer and are committed to creating an inclusive environment for everyone, regardless of race, colour, ancestry, religion, sex, national origin, sexual orientation, age, citizenship, marital status, disability, or gender identity.&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.com">Jobs in Germany</a> on Arbeitnow</a>

&lt;h3 data-start=&quot;321&quot; data-end=&quot;341&quot;&gt;&lt;strong data-start=&quot;325&quot; data-end=&quot;339&quot;&gt;About HEADBORNE.AI&lt;/strong&gt;&lt;/h3&gt;
&lt;p data-start=&quot;342&quot; data-end=&quot;621&quot;&gt;Safe, mission-based AI solutions for first responders and defense.&lt;/p&gt;
&lt;p data-start=&quot;342&quot; data-end=&quot;621&quot;&gt;HEADBORNE&#39;s long-term mission is to defend free democracies of the world with ethical, interoperable, mission-based safe AI solutions for first responders, defense forces, and decision makers. We build a secure, AI-driven Cloud/OS platform integrated in the next generations of AR smart glasses, helmets, drones, robots, and training systems. We seamlessly connect them across air, land, sea, space, and cyberspace, delivering complete situational awareness, control, and command.&lt;/p&gt;
&lt;hr data-start=&quot;812&quot; data-end=&quot;815&quot;&gt;
&lt;h3 data-start=&quot;817&quot; data-end=&quot;835&quot;&gt;&lt;strong data-start=&quot;821&quot; data-end=&quot;833&quot;&gt;About the Role&lt;/strong&gt;&lt;/h3&gt;
&lt;p data-pm-slice=&quot;1 1 []&quot;&gt;HEADBORNE seeks a Senior Embedded Linux/Android Software Engineer to join our rapidly growing team. Our core systems engineers are building the embedded intelligence behind next-generation AI edge devices for defense, forces and first responders.&lt;/p&gt;
&lt;p data-pm-slice=&quot;1 1 []&quot;&gt;&lt;br data-start=&quot;1856&quot; data-end=&quot;1859&quot;&gt;You will develop and integrate software for AI-enabled systems, driving advanced sensing, communications, and SOC/MCU integration. This is a hands-on, high-impact role spanning embedded architecture, system optimization, and mission-critical software reliability.&lt;/p&gt;
&lt;p data-pm-slice=&quot;1 1 []&quot;&gt;&lt;br data-start=&quot;2122&quot; data-end=&quot;2125&quot;&gt;We’re looking for a brilliant, motivated engineer to join TEAM HEADBORNE—delivering mission-based, safe AI solutions that matter.&lt;/p&gt;
&lt;hr&gt;
&lt;h3 data-start=&quot;817&quot; data-end=&quot;835&quot;&gt;&lt;strong data-start=&quot;821&quot; data-end=&quot;833&quot;&gt;Responsibilities&lt;/strong&gt;&lt;/h3&gt;
&lt;ul data-start=&quot;1236&quot; data-end=&quot;1680&quot;&gt;
&lt;li data-start=&quot;1236&quot; data-end=&quot;1348&quot;&gt;
&lt;p data-start=&quot;1238&quot; data-end=&quot;1348&quot;&gt;Own and lead the implementation of software solutions for mission-critical imaging systems.&lt;/p&gt;
&lt;/li&gt;
&lt;li data-start=&quot;1236&quot; data-end=&quot;1348&quot;&gt;
&lt;p data-start=&quot;1238&quot; data-end=&quot;1348&quot;&gt;Write efficient, well-tested code in C++ and Python&lt;/p&gt;
&lt;/li&gt;
&lt;li data-start=&quot;1236&quot; data-end=&quot;1348&quot;&gt;
&lt;p data-start=&quot;1238&quot; data-end=&quot;1348&quot;&gt;Develop low-latency, high-bandwidth processing pipelines for airborne imaging sensors.&lt;/p&gt;
&lt;/li&gt;
&lt;li data-start=&quot;1236&quot; data-end=&quot;1348&quot;&gt;Jump into and understand large codebases.&lt;/li&gt;
&lt;li data-start=&quot;1236&quot; data-end=&quot;1348&quot;&gt;
&lt;p data-start=&quot;1238&quot; data-end=&quot;1348&quot;&gt;Develop device drivers and perform hardware integration (IMX 95, AR Vision, Wi-Fi, Bluetooth, Audio, LCD, Backlight, Power Management, Battery/Charger management, Camera).&lt;/p&gt;
&lt;/li&gt;
&lt;li data-start=&quot;1236&quot; data-end=&quot;1348&quot;&gt;
&lt;p data-start=&quot;1238&quot; data-end=&quot;1348&quot;&gt;Perform board bring-up, bootloader customization, and root filesystem generation.&lt;/p&gt;
&lt;/li&gt;
&lt;li data-start=&quot;1236&quot; data-end=&quot;1348&quot;&gt;
&lt;p data-start=&quot;1238&quot; data-end=&quot;1348&quot;&gt;Integrate and adapt open-source software for embedded platforms.&lt;/p&gt;
&lt;/li&gt;
&lt;li data-start=&quot;1236&quot; data-end=&quot;1348&quot;&gt;Define and implement embedded software architectures (daemons, libraries, device drivers).&lt;/li&gt;
&lt;li data-start=&quot;1236&quot; data-end=&quot;1348&quot;&gt;
&lt;p data-start=&quot;1238&quot; data-end=&quot;1348&quot;&gt;Collaborate with hardware engineers to define embedded hardware architectures.&lt;/p&gt;
&lt;/li&gt;
&lt;li data-start=&quot;1236&quot; data-end=&quot;1348&quot;&gt;
&lt;p data-start=&quot;1238&quot; data-end=&quot;1348&quot;&gt;Contribute to team leadership, project management, and cross-functional collaboration.&lt;/p&gt;
&lt;/li&gt;
&lt;li data-start=&quot;1236&quot; data-end=&quot;1348&quot;&gt;
&lt;p data-start=&quot;1238&quot; data-end=&quot;1348&quot;&gt;Develop and maintain server-side administration tools (package management, deployment, and build systems).&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;hr data-start=&quot;1682&quot; data-end=&quot;1685&quot;&gt;
